// 精确原开训头与教学/开店头互斥；下界复用原永久课程，不倒算同tick迟答。
#include "resident/domains/growth/growth_military_training_qualification.hpp"
#include "resident/domains/growth/growth_tactic_lesson_qualification.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {Integer checks=0;void check(bool ok,const char* label){++checks;if(!ok)throw std::runtime_error(label);}}
int main(){try{
 auto catalog=std::make_shared<CommonCatalog>();catalog->actor_ids={"student"};catalog->actor_initial_birth.insert("student",-14400);FamilyCatalog family;IdentityPrototype original;original.skills.tactics=290;original.skills.infantry=100;original.skills.archery=100;original.skills.cavalry=300;original.skills.transport=300;family.prototypes.insert("student",original);FamilyState identities;GrowthSkillOriginContext origins{*catalog,family,identities,nullptr};CommonState seed;seed.identity.tick=4;seed.next_instance_id=100;ActorRecord actor;actor.id="student";actor.skills=original.skills;actor.skills.tactics=330;seed.actors.insert(actor.id,actor);CommonStore c(seed,catalog);GrowthState state;
 auto study=[&](StableId id,Integer tick,Integer gain){StudyFact f;f.actor_id="student";f.start_tick=0;f.phase="completed";f.completed_tick=tick;f.terms.student_id="student";f.terms.skill_id="tactics";f.terms.settlement_policy="per_lesson_v1";StudyLesson l;l.segment=StudySegment{1,tick,290,10000,gain,false,{},{}};f.lessons.push_back(l);state.facts.insert(id,f);c.state().facts.insert(id,{id,"skill_study","cultivation"});};
 study("action:80",3,10);c.state().facts.insert("action:10",{"action:10","military_training","military"});study("action:5",4,30);c.state().facts.insert("tactic_lesson:90",{"tactic_lesson:90","tactic_lesson_started","growth_tactic_lessons"});const auto before=encode_common_state(c.state());
 auto read=[&](StableId skill,Integer tick,StableId id){return read_growth_military_training_qualification_before_start(c,origins,state,"student",skill,tick,id);};
 auto valid=read("tactics",4,"action:10");check(valid.ok&&valid.value.minimum_xp==300&&valid.value.minimum_level==2,"prior tick threshold proved");check(valid.value.study_source_ids==std::vector<StableId>{"action:80"},"same tick later source excluded");check(valid.value.boundary_fact_id=="action:10"&&valid.value.observed_tick==4,"actual training boundary preserved");auto same=read("tactics",3,"action:10");check(same.ok&&same.value.minimum_xp==290,"same tick earlier source also excluded");for(auto skill:{"infantry","archery","cavalry","transport"})check(read(skill,4,"action:10").ok,"fixed skill permitted");
 check(!read("commerce",4,"action:10").ok,"unrelated skill refused");check(!read("tactics",4,{}).ok,"empty boundary refused");check(!read("tactics",5,"action:10").ok,"future refused");check(!read("tactics",4,"tactic_lesson:90").ok,"lesson does not impersonate training");check(!read_growth_tactic_lesson_qualification_before_start(c,origins,state,"student","tactics",4,"action:10").ok,"lesson reader remains narrow");check(!read_commerce_study_qualification_before_opening(c,origins,state,"student",4,"action:10").ok,"shop reader remains narrow");
 c.state().facts.find("action:10")->domain="cultivation";check(!read("tactics",4,"action:10").ok,"wrong domain refused");c.state().facts.find("action:10")->domain="military";c.state().facts.find("action:10")->kind="military_training_finished";check(!read("tactics",4,"action:10").ok,"completion cannot impersonate start");c.state().facts.find("action:10")->kind="military_training";check(compare_boundary(before,encode_common_state(c.state())).exact(),"reads preserve bytes");std::cout<<"GROWTH_MILITARY_TRAINING_QUALIFICATION "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
